import test from 'node:test';
import assert from 'node:assert/strict';
import {Game,RESONATOR} from '../dist/game.js';
test('resonator requires proximity and accepts only the motif',()=>{const g=new Game();g.interact();assert.equal(g.mode,'explore');Object.assign(g.player,RESONATOR);g.interact();assert.equal(g.mode,'puzzle');assert.equal(g.note(2),false);assert.deepEqual(g.notes,[]);[1,3,2].forEach(n=>g.note(n));assert.equal(g.mode,'battle');assert.equal(g.player.hp,5);});
test('diagonal movement stays in the arena',()=>{const g=new Game();for(let i=0;i<1000;i++)g.step(.05,{x:1,y:1});assert.ok(Math.hypot(g.player.x,g.player.y)<=.940001);});
test('attack requires proximity, and pulse consumes resonance',()=>{const g=new Game();g.mode='battle';g.attack();assert.equal(g.boss.hp,300);g.player.attack=0;g.player.y=-.4;g.attack();assert.equal(g.boss.hp,292);g.player.res=39;assert.equal(g.pulse(),false);g.player.res=40;assert.equal(g.pulse(),true);assert.equal(g.player.res,0);assert.equal(g.boss.hp,260);});
test('dodge blocks damage for its window and has a cooldown',()=>{const g=new Game();g.mode='battle';g.dodge();g.hurt();assert.equal(g.player.hp,5);g.dodge();assert.equal(g.player.dodge,.72);for(let i=0;i<7;i++)g.step(.05);g.hurt();assert.equal(g.player.hp,4);});
test('phase transition clears hazards and telegraphs last over one second',()=>{const g=new Game();g.mode='battle';g.bullets.push({x:0,y:0,vx:0,vy:0});g.damageBoss(100);assert.equal(g.boss.phase,2);assert.equal(g.bullets.length,0);g.nextPattern=0;g.step(.01);assert.ok(g.pending.at-g.time>=1.09);for(let i=0;i<20;i++)g.step(.05);assert.ok(g.pending);});
test('parry reflects marked projectiles and rewards resonance',()=>{const g=new Game();g.mode='battle';g.nextPattern=100;g.parry();g.bullets.push({x:g.player.x,y:g.player.y,vx:0,vy:0,reflectable:true});g.step(.01);assert.equal(g.reflected,1);assert.equal(g.player.hp,5);assert.equal(g.player.res,54);assert.equal(g.boss.hp,288);});
test('death and victory have replayable terminal states',()=>{const g=new Game();g.mode='battle';for(let i=0;i<5;i++){g.player.inv=0;g.hurt();}assert.equal(g.mode,'dead');g.reset();g.mode='battle';g.damageBoss(300);assert.equal(g.mode,'choice');assert.equal(g.bullets.length,0);g.choose('keep');assert.equal(g.mode,'ended');assert.equal(g.ending,'keep');g.reset();assert.equal(g.mode,'explore');assert.equal(g.player.hp,5);});
test('beam locks its warning direction so lateral movement can evade it',()=>{const g=new Game();g.mode='battle';g.boss.phase=2;g.nextPattern=0;g.player.x=0;g.player.y=.2;g.step(.01);assert.equal(g.pending.pattern,'beam');const angle=g.pending.angle;for(let i=0;i<23;i++)g.step(.05,{x:1,y:0});assert.equal(g.player.hp,5);assert.ok(g.beam);assert.equal(g.beam.angle,angle);assert.ok(g.player.x>.6);});
test('standing in the central safe spot cannot damage the boss with melee',()=>{const g=new Game();g.mode='battle';g.player.y=.3;for(let i=0;i<100;i++){g.attack();g.step(.05);}assert.equal(g.boss.hp,300);});
